var dbAll=function(st){return tx(st,'readonly',function(s){return s.getAll()}).then(function(rs){var lock=[];return Promise.all(rs.map(function(r){return decRec(st,r).catch(function(){lock.push(r);return null})})).then(function(out){out=out.filter(function(x){return x!==null&&x!==undefined});return lock.length?quarantine(st,lock).then(function(){return out}):out})})},dbPut=function(st,v){return encRec(st,v).then(function(r){return tx(st,'readwrite',function(s){return s.put(r)})})},dbDel=function(st,k){return tx(st,'readwrite',function(s){return s.delete(k)})};
