function regen(){var c=cur(),old=c.plan,np=E.planWeek(ec(c),D,{phrases:old.phr});np.days.forEach(function(d,i){d.slots.forEach(function(sl){var o=old.days[i].slots.filter(function(x){return x.si===sl.si})[0];if(o&&o.time)sl.time=o.time})});c.plan=np;save();main();toast('تم تطبيق التوزيع على الأيام السبعة')}
function dlFile(blob,name){if(window.HNative&&HNative.isNative()){HNative.saveFile(blob,name).then(function(r){if(r&&!r.shared)toast('حُفظ الملف مؤقتاً لكن لم تُفتح ورقة المشاركة')}).catch(function(e){toast('تعذّر حفظ الملف: '+(e&&e.message||e))});return}var a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download=String(name).replace(/[\\/:*?"<>|\s]+/g,'_');a.style.display='none';document.body.appendChild(a);a.click();setTimeout(function(){a.remove();URL.revokeObjectURL(u)},1500)}
function fileBase(c){return'DietPlan_'+c.code+'_'+new Date().toISOString().slice(0,10)}

