// ================= بطاقة «تطبيق الجوال»: روابط التنزيل والتحديث (يحرّرها المدير وتصل المستخدمين مع نسخة المستخدمين) =================
function appCfg(){return eff().app||{}}
function appHas(){var a=appCfg();return !!(a.apk||a.ios||a.play||a.web)}
function appUpdate(){var a=appCfg();return a.version&&S.appVer&&window.HNative&&HNative.cmpVersion(S.appVer,a.version)<0?a.version:''}
function httpsOk(u){return /^https:\/\/[^\s]+$/i.test(String(u||'').trim())}
function appCard(){
  var a=appCfg();if(!appHas())return'';var ua=navigator.userAgent||'',isAnd=/Android/i.test(ua),isIos=/iPhone|iPad|iPod/i.test(ua),up=appUpdate();
  var items=[['apk','أندرويد — ملف APK للتنزيل المباشر',a.apk,isAnd],['play','متجر Google Play',a.play,isAnd],['ios','آيفون — App Store أو TestFlight',a.ios,isIos],['web','التثبيت من المتصفح (PWA) — أندرويد وآيفون',a.web,false]].filter(function(x){return x[2]&&httpsOk(x[2])});
  return'<div class="appcard">'+(up?'<div class="gok">🔔 تحديث متاح: الإصدار '+esc(up)+(S.appVer?' (أنت على '+esc(S.appVer)+')':'')+'</div>':'')+'<h3>📲 تطبيق «حصة» للجوال</h3>'+(a.version?'<p class="small">آخر إصدار: <b>'+esc(a.version)+'</b>'+(a.notes?' — '+esc(a.notes):'')+'</p>':'')
  +items.map(function(x){return'<div class="applink'+(x[3]?' rec':'')+'"><div><b>'+x[1]+'</b>'+(x[3]?' <small class="cu">الأنسب لجهازك</small>':'')+'<br><small dir="ltr">'+esc(x[2])+'</small></div><div class="applb"><button class="sm" data-a="appOpen" data-u="'+esc(x[2])+'">فتح / تنزيل</button> <button class="sec sm" data-a="appCopy" data-u="'+esc(x[2])+'">نسخ الرابط</button> <button class="sec sm" data-a="appShare" data-u="'+esc(x[2])+'" data-t="'+esc(x[1])+'">مشاركة</button></div></div>'}).join('')
  +(isIos&&a.web?'<p class="small">آيفون: افتح رابط التثبيت في Safari ← زر المشاركة ← «إضافة إلى الشاشة الرئيسية».</p>':'')+(isAnd&&a.apk?'<p class="small">أندرويد: بعد التنزيل اسمح بالتثبيت من هذا المصدر عندما يطلب الجهاز.</p>':'')+'</div>'}
function appPage(){
  var a=appCfg(),fld2=function(k,l,ph,dir){return'<div><label>'+l+'</label><input data-ap="'+k+'" '+(dir?'dir="ltr" ':'')+'placeholder="'+ph+'" value="'+esc((S.settings.app||{})[k]||'')+'"></div>'};
  if(S.mode!=='admin')return(appHas()?appCard():'<p class="small">لم يضف المدير رابط تنزيل التطبيق بعد.</p>');
  return'<p class="small">روابط تنزيل وتحديث تطبيق الجوال. تظهر للمستخدمين في صفحتهم الرئيسية وهذا التبويب، وتصلهم عند «تصدير نسخة المستخدمين». الروابط يجب أن تبدأ بـ https://</p><div class="addbox"><div class="row">'+fld2('apk','رابط ملف APK (تنزيل مباشر لأندرويد)','https://example.com/hissa.apk',1)+fld2('play','رابط Google Play','https://play.google.com/store/apps/details?id=…',1)+fld2('ios','رابط App Store أو TestFlight','https://apps.apple.com/…',1)+fld2('web','رابط التثبيت من المتصفح (PWA)','https://example.com/',1)+fld2('version','آخر إصدار (مثال 1.2.0)','1.0.0',1)+fld2('notes','ملاحظة قصيرة (اختيارية)','تحسينات وإصلاحات')+'</div></div><h3>معاينة ما يراه المستخدم</h3>'+(appHas()?appCard():'<p class="small">أضف رابطاً واحداً على الأقل لتظهر البطاقة.</p>')
}
Object.assign(A,{
  appOpen:function(v,el){var u=el.dataset.u;if(!httpsOk(u)){toast('الرابط غير صالح');return}HNative.openUrl(u)},
  appCopy:function(v,el){var u=el.dataset.u;(navigator.clipboard?navigator.clipboard.writeText(u):Promise.reject()).then(function(){toast('تم نسخ الرابط')},function(){toast('تعذّر النسخ — انسخه يدوياً')})},
  appShare:function(v,el){HNative.share({title:'تطبيق حصة',text:'حمّل تطبيق «حصة» — '+el.dataset.t,url:el.dataset.u}).then(function(r){toast(r==='copied'?'تم نسخ الرابط':r==='shared'?'تمت المشاركة':'')})}
});
document.addEventListener('change',function(e){var t=e.target;if(t.dataset&&t.dataset.ap&&S.mode==='admin'){var k=t.dataset.ap,v=t.value.trim(),a=S.settings.app=S.settings.app||{};if(k!=='version'&&k!=='notes'&&v&&!httpsOk(v)){toast('الرابط يجب أن يبدأ بـ https:// ولا يحوي مسافات');t.value=a[k]||'';return}if(k==='version'&&v&&!/^\d+(\.\d+){0,3}$/.test(v)){toast('الإصدار أرقام تفصلها نقاط، مثل 1.2.0');t.value=a[k]||'';return}if(v)a[k]=v;else delete a[k];saveSettings();var m=$('main');if(m&&S.setTab==='app'){var keep=t.dataset.ap;main();var nx=$('[data-ap="'+keep+'"]');if(nx)nx.focus()}}});

// ================= الأرشيف المقفل: سجلات مشفّرة بمفتاح سابق (بعد إعادة ضبط كلمة السر/إعادة إنشاء الحساب). لا تُحذف ولا تُكتب فوقها.
function renderFatal(e){var m=$('main');if(!m)return;try{console.error(e)}catch(_){}m.innerHTML='<div class="gerr" style="margin:12px"><h3>تعذّر عرض هذه الصفحة</h3><p>حدث خطأ غير متوقع. <b>بياناتك لم تُحذف.</b> جرّب إعادة التحميل، وإن تكرّر فأرسل لي النص التقني أدناه.</p><p class="small" dir="ltr" style="word-break:break-all">'+esc(((e&&e.name)||'Error')+': '+((e&&e.message)||String(e)))+'</p><p><button data-a="reloadPg">إعادة التحميل</button> <button class="sec" data-a="lock">🔒 قفل</button></p></div>'}
function lgNums(){var c=0,v=0,o=0;(S.legacyRecs||[]).forEach(function(x){if(x.st==='clients')c++;else if(x.st==='versions')v++;else o++});return{c:c,v:v,o:o,t:c+v+o}}
function legacyBanner(){var m=$('main'),old=$('#lgbn');if(old)old.remove();var n=lgNums();if(!m||!n.t)return;m.insertAdjacentHTML('afterbegin','<div class="lgbn" id="lgbn"><b>⚠ بيانات قديمة غير قابلة للقراءة ('+n.c+' عميل، '+n.v+' إصدار)</b><br>وُجدت بيانات محفوظة على هذا الجهاز بمفتاح تشفير سابق — يحدث عادةً بعد أن يعيد المدير ضبط كلمة سرّك أو ينشئ حسابك من جديد. <b>لم تُحذف</b>؛ نُقلت إلى «الأرشيف المقفل» وبقية التطبيق يعمل بصورة طبيعية.<p>'+(CFG.legacyKeys?'<button class="sm" data-a="lgUnlock">فكّها بكلمة السر القديمة</button> ':'')+'<button class="sec sm" data-a="lgDownload">تنزيل نسخة مشفّرة</button> <button class="r sm" data-a="lgDelete">حذفها نهائياً</button></p><small class="small">إن كانت لديك «نسخة احتياطية» سابقة فاستعملها من «استرجاع» أسفل القائمة.</small></div>')}
function nextCode(){return'C'+String(S.clients.reduce(function(a,c){return Math.max(a,parseInt(c.code.slice(1))||0)},0)+1).padStart(4,'0')}
function restoreLegacy(keys){
  var recs=(S.legacyRecs||[]).slice().sort(function(a,b){var o={clients:0,versions:1,meta:2};return o[a.st]-o[b.st]}),done=0,fail=0,map={},live={};S.clients.forEach(function(c){live[c.code]=1});
  var tryDec=function(raw){var i=0;function nx(){if(i>=keys.length)return Promise.resolve(null);return HS.decJSON(keys[i++],raw).then(function(o){return o},nx)}return nx()};
  return recs.reduce(function(p,L){return p.then(function(){return tryDec(L.raw).then(function(o){if(!o){fail++;return}var pr;
    if(L.st==='clients'){var old=o.code;if(live[o.code]){o.code=nextCode();while(live[o.code])o.code='C'+String((parseInt(o.code.slice(1))||0)+1).padStart(4,'0');map[old]=o.code}live[o.code]=1;o.updated=Date.now();pr=dbPut('clients',o).then(function(){S.clients.push(o)})}
    else if(L.st==='versions'){delete o.id;if(map[o.code])o.code=map[o.code];pr=dbPut('versions',o)}else pr=Promise.resolve();
    return pr.then(function(){return dbDel('meta',L.key)}).then(function(){S.legacyRecs=S.legacyRecs.filter(function(x){return x!==L});done++})})})},Promise.resolve()).then(function(){return{done:done,fail:fail}})}
Object.assign(A,{
  reloadPg:function(){location.reload()},
  lgDownload:function(){var o={app:'dietpro-web-locked',at:Date.now(),note:'سجلات مشفّرة بمفتاح قديم — لا تحتوي نصاً مقروءاً',records:S.legacyRecs.map(function(x){return{st:x.st,rk:x.rk,raw:x.raw}})};dlFile(new Blob([JSON.stringify(o)],{type:'application/json'}),'hissa_locked_archive_'+new Date().toISOString().slice(0,10)+'.json');toast('نُزِّلت نسخة مشفّرة من الأرشيف المقفل')},
  lgDelete:function(){var n=lgNums();if(!confirm('سيُحذف نهائياً: '+n.c+' عميل و'+n.v+' إصدار من الأرشيف المقفل، ولا يمكن استرجاعها.\nهل نزّلتَ نسخة مشفّرة قبل ذلك؟ اضغط «موافق» للمتابعة.'))return;if(!confirm('تأكيد أخير: حذف الأرشيف المقفل نهائياً؟'))return;var ks=S.legacyRecs.map(function(x){return x.key});Promise.all(ks.map(function(k){return dbDel('meta',k)})).then(function(){S.legacyRecs=[];main();toast('حُذف الأرشيف المقفل')})},
  lgUnlock:function(){var pw=prompt('أدخل كلمة السر القديمة لهذا الحساب (التي كنت تدخل بها قبل إعادة الضبط):');if(pw===null||pw==='')return;CFG.legacyKeys(pw).then(function(keys){if(keys.length)return keys;var tk=prompt('لا يوجد مفتاح قديم محفوظ على هذا الجهاز.\nإن كان لديك كود التفعيل القديم الذي أُرسل إليك سابقاً (قبل إعادة الضبط) فالصقه هنا:');if(!tk)return[];return CFG.legacyKeys(pw,tk.replace(/\s+/g,''))}).then(function(keys){if(!keys.length){toast('تعذّر: كلمة السر أو الكود القديم غير مطابق');return}return restoreLegacy(keys).then(function(r){S.clients.sort(function(a,b){return a.code<b.code?-1:1});render();toast('استُرجع '+r.done+' سجل'+(r.fail?' — تعذّر فكّ '+r.fail:''))})}).catch(function(e){toast('تعذّرت الاستعادة: '+(e&&e.message||e))})}
});
function header(){var h=$('#hd'),left=CFG.exp?Math.ceil((CFG.exp*1000-Date.now())/86400000):null;h.innerHTML='<button class="sec sm" id="menuBtn" data-a="menu" aria-label="القائمة">☰</button><img class="hlogo" src="'+window.ASSETS.dark+'" alt="حصة"><label class="hsrch gonly">'+IC('search')+'<input id="hq" type="search" placeholder="بحث عن عميل" aria-label="بحث عن عميل"></label><span class="hinfo">'+esc(CFG.userLabel||'')+(left!==null?' • ينتهي التفعيل بعد '+left+' يوم'+(left<=7?' ⚠ جدّد الكود':''):'')+'</span>'+themeBtn()+'<button class="sec sm" data-a="lock">🔒 قفل</button><span class="uchip gonly" title="'+esc(CFG.userLabel||'')+'"><span class="cav">'+esc(initial(firstName()))+'</span><span><b>'+esc(firstName())+'</b>'+(left!==null?'<small'+(left<=7?' class="warn"':'')+'>ينتهي التفعيل بعد '+left+' يوم</small>':'')+'</span></span>'}
window.HApp={start:function(cfg){CFG=cfg;window.__appStarted=true;try{if(navigator.storage&&navigator.storage.persist)navigator.storage.persist().catch(function(){})}catch(e){}if(window.HNative)HNative.appInfo().then(function(i){if(i){S.appVer=i.version;if(!S.cur&&S.view==='client')main()}});DKEY=cfg.key||null;S.legacyRecs=[];S.mode=cfg.mode;S.base=cfg.base||null;header();var lt;function bump(){clearTimeout(lt);if(cfg.stay)return;lt=setTimeout(function(){location.reload()},(cfg.lockMin||30)*60000)}['click','keydown','mousemove','touchstart'].forEach(function(ev){document.addEventListener(ev,bump,{passive:true})});bump();
return open().then(function(){return dbAll('meta')}).then(function(m){var r=m.filter(function(x){return x.key==='settings'})[0];if(r)S.settings=Object.assign({colors:{},over:{},deleted:[],custom:[]},r);S.legacyRecs=S.legacyRecs.concat(m.filter(function(x){return x&&x.legacy}));var ac=m.filter(function(x){return x&&x.key==='aiconsent'})[0];S.aiConsent=!!(ac&&ac.ok);applyS();return dbAll('clients')}).then(function(a){S.clients=a;return S.legacyRecs.length?dbAll('versions'):0}).then(function(){render()}).catch(function(e){renderFatal(e)})},
refresh:function(){render()},reencrypt:function(newKey){var stores=['clients','versions','meta'],plain={};return Promise.all(stores.map(function(st){return tx(st,'readonly',function(x){return x.getAll()}).then(function(rs){return Promise.all(rs.map(function(r){return decRec(st,r)}))}).then(function(v){plain[st]=v})})).then(function(){var old=DKEY;DKEY=newKey;return Promise.all(stores.map(function(st){return Promise.all(plain[st].map(function(v){return dbPut(st,v)}))})).catch(function(e){DKEY=old;throw e})})},getSettings:function(){return JSON.parse(JSON.stringify(S.settings))},download:dlFile,toast:toast,state:S};
